export function scoreQuiz(questions,answers,times=[]){const correct=questions.filter((q,i)=>answers[i]===q.answer).length;const skipped=questions.filter((_,i)=>answers[i]==null).length;const attempted=questions.length-skipped;return {correct,skipped,wrong:attempted-correct,total:questions.length,attempted,score:questions.length?Math.round(correct/questions.length*100):0,accuracy:attempted?Math.round(correct/attempted*100):0,totalSeconds:times.reduce((a,b)=>a+(Number(b)||0),0)};}
export function recordTime(times,index,start,now){const copy=[...times];copy[index]=(copy[index]||0)+Math.max(0,now-start)/1000;return copy;}
export function validateBackup(b){if(b?.app!=='exam-dost'||b.version!==1||!b.state||typeof b.state!=='object')throw Error('Not an Exam Dost backup.');const s=b.state; if(s.profile&&(!['name','college','branch'].every(k=>typeof s.profile[k]==='string'&&s.profile[k].trim().length>0&&s.profile[k].length<250)))throw Error('Invalid profile.');for(const k of ['attempts','tasks','saved','marked'])if(s[k]!==undefined&&!Array.isArray(s[k]))throw Error('Invalid '+k);for(const k of ['topics','settings','exams'])if(s[k]!==undefined&&(!s[k]||typeof s[k]!=='object'||Array.isArray(s[k])))throw Error('Invalid '+k);if((s.attempts||[]).some(a=>!a||!Array.isArray(a.questions)||a.questions.length===0||!Array.isArray(a.answers)||!Array.isArray(a.times)||!Number.isInteger(a.index)||a.index<0||a.index>=a.questions.length||a.answers.length!==a.questions.length||a.times.length!==a.questions.length||a.times.some(t=>!Number.isFinite(t)||t<0)||!a.questions.every(q=>typeof q.text==='string'&&Array.isArray(q.options)&&q.options.every(o=>typeof o==='string')&&Number.isInteger(q.answer)&&q.answer>=0&&q.answer<q.options.length)))throw Error('Invalid quiz history.');if((s.tasks||[]).some(t=>!t||typeof t.id!=='string'||typeof t.title!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(t.date)))throw Error('Invalid planner tasks.');return s;}
export function yearCounts(questions,years,n=6){return Array.from({length:n},(_,i)=>years.map(y=>questions.filter(q=>q.unit===i+1).reduce((a,q)=>a+(q.source?.year!=null?[q.source.year]:q.years||[]).filter(v=>v===y).length,0)));}
export function dateKey(d=new Date()){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
export function buildPlan(topics,completed,start,availability,exams){let remaining=topics.filter(t=>!completed[t.id]);remaining.sort((a,b)=>(exams[a.subject]||'9999').localeCompare(exams[b.subject]||'9999'));let tasks=[];let idx=0;for(let day=0;day<60&&idx<remaining.length;day++){let d=new Date(start+'T12:00:00');d.setDate(d.getDate()+day);const slots=Math.floor((availability[d.getDay()]||0)/30);for(let j=0;j<slots&&idx<remaining.length;j++){let t=remaining[idx++];tasks.push({id:uid(),topic:t.id,title:t.title,subject:t.subject,date:dateKey(d),minutes:30,status:'pending',auto:true});}}return tasks;}

export function uid(provider=crypto){if(provider.randomUUID)return provider.randomUUID();return Array.from(provider.getRandomValues(new Uint32Array(4)),n=>n.toString(36)).join('-');}
